package com.yuyutian.mytools.messaging.controller;
import com.yuyutian.mytools.messaging.model.*;import com.yuyutian.mytools.messaging.service.*;import jakarta.validation.Valid;import jakarta.validation.constraints.Pattern;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
/** 问题反馈迁移接口。 */ @Validated @RestController @RequestMapping("/internal/v1/support-feedback/migrations") public class SupportFeedbackMigrationController {private final InternalRequestAuthorizer authorizer;private final SupportFeedbackMigrationService service;/** 创建控制器。 @param authorizer 授权 @param service 服务 */ public SupportFeedbackMigrationController(InternalRequestAuthorizer authorizer,SupportFeedbackMigrationService service){this.authorizer=authorizer;this.service=service;}
 /** 导入旧反馈。 @param authorization 授权 @param batch 批次 @return 结果 */ @PostMapping("/legacy") public LegacyFeedbackMigrationResult migrate(@RequestHeader("Authorization")String authorization,@Valid @RequestBody LegacyFeedbackBatch batch){authorizer.requireAuthorized(authorization);return service.migrate(batch);}
 /** 对账迁移结果。 @param authorization 授权 @param migrationKey 迁移键 @return 对账 */ @GetMapping("/legacy/reconciliation") public FeedbackReconciliation reconcile(@RequestHeader("Authorization")String authorization,@RequestParam @Pattern(regexp="[A-Za-z0-9._:-]{1,128}")String migrationKey){authorizer.requireAuthorized(authorization);return service.reconcile(migrationKey);}
}
